import React, { useState, useEffect } from "react";
import { 
  DashboardIcon, 
  UsersIcon, 
  TasksIcon, 
  MetricsIcon, 
  SettingsIcon,
  CloseIcon
} from "./Icons";

interface SidebarProps {
  isOpen: boolean;
  onToggle: () => void;
  currentView: string;
  onViewChange: (view: string) => void;
}

const menuItems = [
  {
    id: "dashboard",
    name: "Dashboard",
    icon: DashboardIcon,
  },
  {
    id: "clients",
    name: "Clients",
    icon: UsersIcon,
  },
  {
    id: "tasks",
    name: "Tasks",
    icon: TasksIcon,
  },
  {
    id: "metrics",
    name: "Metrics",
    icon: MetricsIcon,
  },
  {
    id: "settings",
    name: "Settings",
    icon: SettingsIcon,
  },
];

export const Sidebar: React.FC<SidebarProps> = ({
  isOpen,
  onToggle,
  currentView,
  onViewChange,
}) => {
  const [systemStatus, setSystemStatus] = useState({
    status: 'operational' as 'operational' | 'warning' | 'error',
    message: 'All systems operational',
    color: 'bg-green-500',
    bgColor: 'bg-green-100'
  });

  // Простий статус без автоматичного перемикання
  useEffect(() => {
    // Можна додати реальну логіку перевірки статусу тут
    const currentStatus = {
      status: 'operational' as const,
      message: 'All systems operational',
      color: 'bg-green-500',
      bgColor: 'bg-green-100'
    };
    setSystemStatus(currentStatus);
  }, []);

  const renderSystemStatus = () => (
    <div className="group relative glass-colored rounded-xl border border-secondary-200 shadow-xl transition-all duration-300 hover:shadow-2xl cursor-pointer overflow-hidden card-hover animate-floating">
      <div className={`flex items-center transition-all duration-300 ${isOpen ? 'p-4' : 'p-3 justify-center'}`}>
        {/* Статус індикатор */}
        <div className={`gradient-success rounded-full flex items-center justify-center shadow-lg transition-all duration-200 animate-glow-success ${isOpen ? 'w-10 h-10' : 'w-12 h-12'}`}>
          <div className={`w-4 h-4 bg-white rounded-full ${systemStatus.status === 'operational' ? 'animate-bounce-gentle' : 'animate-pulse'}`}></div>
        </div>

        {/* Текстова інформація - тільки коли відкритий */}
        {isOpen && (
          <div className="ml-3 min-w-0 flex-1">
            <p className="text-xs font-medium text-secondary-900 truncate">
              System Status
            </p>
            <p className="text-xs text-secondary-500 truncate">
              {systemStatus.message}
            </p>
          </div>
        )}
      </div>

      {/* Tooltip для згорнутого стану */}
      {!isOpen && (
        <div className="absolute left-full ml-2 top-1/2 transform -translate-y-1/2 bg-secondary-900 text-white text-xs rounded px-2 py-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none z-50 whitespace-nowrap">
          {systemStatus.message}
        </div>
      )}
    </div>
  );

  return (
    <>
      {/* Desktop Sidebar */}
      <div
        className={`hidden lg:flex lg:flex-col lg:fixed lg:inset-y-0 transition-all duration-300 ${
          isOpen ? "lg:w-64" : "lg:w-16"
        }`}
      >
        <div className="flex flex-col flex-grow bg-white shadow-sm border-r border-secondary-200">
          {/* Logo section */}
          <div className="flex items-center flex-shrink-0 px-4 py-6">
            <div className="flex items-center">
              <div className="flex-shrink-0 w-10 h-10 gradient-rainbow rounded-xl flex items-center justify-center shadow-xl animate-rainbow-glow animate-morphing">
                <span className="text-sm font-bold text-white animate-text-shimmer">TC</span>
              </div>
              {isOpen && (
                <div className="ml-4 transition-all duration-300 animate-slide-in-right">
                  <h2 className="text-base font-semibold text-gradient neon-glow">
                    TetraCore
                  </h2>
                  <p className="text-xs text-secondary-600 animate-slide-in-left">StreamHub</p>
                </div>
              )}
            </div>
          </div>

          {/* Navigation */}
          <nav className="flex-1 px-2 py-4 space-y-2">
            {menuItems.map((item) => {
              const isActive = currentView === item.id;
              const IconComponent = item.icon;

              return (
                <button
                  key={item.id}
                  onClick={() => onViewChange(item.id)}
                  className={`group flex items-center w-full px-3 py-3 text-sm font-medium rounded-lg transition-all duration-200 hover:scale-105 button-press card-hover ${
                    isActive
                      ? "bg-primary-50 text-primary-700 shadow-sm border-l-4 border-primary-500"
                      : "text-secondary-600 hover:bg-secondary-50 hover:text-secondary-900 hover:shadow-sm"
                  }`}
                >
                  <div
                    className={`flex-shrink-0 transition-all duration-200 hover-icon-scale ${
                      isActive
                        ? "text-primary-500 scale-110 animate-icon-glow"
                        : "text-secondary-400 group-hover:text-secondary-500 group-hover:scale-105"
                    }`}
                  >
                    <IconComponent size="lg" />
                  </div>
                  {isOpen && (
                    <span className="ml-3 transition-all duration-300 opacity-100">
                      {item.name}
                    </span>
                  )}
                  {!isOpen && (
                    <div className="absolute left-16 bg-secondary-900 text-white text-xs rounded px-2 py-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none z-50 whitespace-nowrap">
                      {item.name}
                    </div>
                  )}
                </button>
              );
            })}
          </nav>

          {/* Footer */}
          <div className="flex-shrink-0 p-4">
            {renderSystemStatus()}
          </div>
        </div>
      </div>

      {/* Mobile Sidebar */}
      <div
        className={`lg:hidden fixed inset-0 z-50 transition-transform duration-300 ${
          isOpen ? "translate-x-0" : "-translate-x-full"
        }`}
      >
        <div className="flex">
          {/* Sidebar content */}
          <div className="flex flex-col w-64 bg-white shadow-xl">
            {/* Logo section */}
            <div className="flex items-center justify-between flex-shrink-0 px-4 py-4 border-b border-secondary-200">
              <div className="flex items-center">
                <div className="flex-shrink-0 w-8 h-8 gradient-primary rounded-lg flex items-center justify-center shadow-md">
                  <span className="text-sm font-bold text-white">TC</span>
                </div>
                <div className="ml-3">
                  <h2 className="text-sm font-semibold text-secondary-900">
                    TetraCore
                  </h2>
                  <p className="text-xs text-secondary-500">StreamHub</p>
                </div>
              </div>
              <button
                onClick={onToggle}
                className="p-2 text-secondary-400 hover:text-secondary-500 hover:bg-secondary-100 rounded-full transition-colors duration-200"
              >
                <CloseIcon size="lg" />
              </button>
            </div>

            {/* Navigation */}
            <nav className="flex-1 px-4 py-4 space-y-2 overflow-y-auto">
              {menuItems.map((item) => {
                const isActive = currentView === item.id;
                const IconComponent = item.icon;

                return (
                  <button
                    key={item.id}
                    onClick={() => {
                      onViewChange(item.id);
                      onToggle();
                    }}
                    className={`group flex items-center w-full px-3 py-3 text-sm font-medium rounded-lg transition-all duration-200 button-press card-hover ${
                      isActive
                        ? "bg-primary-50 text-primary-700 shadow-sm border-l-4 border-primary-500"
                        : "text-secondary-600 hover:bg-secondary-50 hover:text-secondary-900 hover:shadow-sm"
                    }`}
                  >
                    <div
                      className={`flex-shrink-0 transition-all duration-200 hover-icon-scale ${
                        isActive
                          ? "text-primary-500 animate-icon-glow"
                          : "text-secondary-400 group-hover:text-secondary-500"
                      }`}
                    >
                      <IconComponent size="lg" />
                    </div>
                    <span className="ml-3">{item.name}</span>
                  </button>
                );
              })}
            </nav>

            {/* Footer */}
            <div className="flex-shrink-0 p-4 border-t border-secondary-200">
              {renderSystemStatus()}
            </div>
          </div>

          {/* Overlay */}
          <div className="flex-1 bg-black bg-opacity-50" onClick={onToggle} />
        </div>
      </div>
    </>
  );
};
